B=[
dict(a=1,z=3,star=3,lit=L(1,3),
key=[('進前來','H5066','vayyigshu','近前'),('從最小的到至大的','H6996','miqqaton','從小到大'),('禱告','H6419','vehitpallel','代禱'),('祈求','H8467','tekhinnatenu','懇求'),('剩下的','H7611','hasheerit','剩下的人'),('所當走的路','H1870','haderekh','路'),('指示','H5046','veyaggid','告訴')],
gram=['**{H6419}**（palal，禱告）：「**為我們這剩下的人禱告耶和華**」。**這是三十七章3節的同一個動詞。****那一次，西底家請耶利米代禱；這一次，是約哈難與眾百姓。**','**{H5046}**（nagad，指示）：「**願耶和華……指示我們所當走的路**」。**這個動詞，是「告訴、使人知道」。****他們求的，是一個答案。**'],
exp=['四十二章，是四十一章結尾的下一步。**四十一章17、18節說：他們停在伯利恆附近的金罕寓，要進入埃及去。****現在，一節說：眾軍長和加利亞的兒子約哈難，並何沙雅的兒子耶撒尼亞，以及眾百姓，從最小的到至大的，都進前來。****請你留意「從最小的到至大的」：這不是少數人的決定，是整個團體。**','二節，他們對先知耶利米說：**求你准我們在你面前祈求，為我們這剩下的人，禱告耶和華你的神。我們本來眾多，現在剩下的極少，這是你親眼所見的。****這是一個很謙卑的開場，很誠實的承認：我們剩下的，極少。****請你注意：二、三節，他們說「耶和華——你的神」；到了六節，才說「耶和華——我們的神」。****這個小小的變化，聖經沒有解釋，我們也不替他們定罪，只記下。**','三節：**願耶和華你的神，指示我們所當走的路，所當做的事。****請你看，他們沒有問「我們可不可以去埃及」；他們問的是：我們該走的路，該做的事。****這是一個很正確的問題。****也是這一章，最令人心痛的地方：問題問得很對，答案出來後，他們卻不聽。**']),
dict(a=4,z=6,star=3,lit=L(4,6),
key=[('聽見','H8085','shamati','聽見'),('毫不隱瞞','H4513','emna','留下、扣留'),('見證','H5707','led','見證'),('真實誠信','H571','emet','真、誠'),('是好是歹','H2896','tov','好'),('得福','H3190','yitav','得好處')],
gram=['**{H4513}**（mana，隱瞞）：「**我必都告訴你們，毫不隱瞞**」。**原文是「我不會留下一句」。****耶利米應許：神說什麼，我就說什麼，一句不留。**','**{H571}**（emet，真實）：「**真實誠信的見證**」。**他們請耶和華，來作他們的見證。****這是一個很重的誓言。**'],
exp=['四節，耶利米的回答：**我已經聽見你們了，我必照著你們的話禱告耶和華你們的神。耶和華無論回答甚麼，我必都告訴你們，毫不隱瞞。****請你留意，這是一位先知的承諾：不增，不減，不隱瞞。****他沒有說：我會替你們挑選比較好的答案。****他說：無論回答什麼，我必都告訴你們。**','五節，他們對耶利米說：**我們若不照耶和華你的神差遣你來說的一切話行，願耶和華在我們中間，作真實誠信的見證。****六節：我們現在請你到耶和華我們的神面前，他說的無論是好是歹，我們都必聽從；我們聽從耶和華我們神的話，就可以得福。****請你一字一字讀：他們起誓，無論是好是歹，都必聽從。****他們請神作見證。****這是這一章，最重的誓言。**','請你記住這一段：**「無論是好是歹，我們都必聽從」。****這句話，在這一章的後半，將要被檢驗。****聖經沒有說他們說謊，也沒有說他們當時不是真誠的；經文只記：他們說了。****我們都有這樣的時刻：在禱告的時候，我們說，主啊，無論是好是歹，我都聽從。****然後，答案來了。**']),
dict(a=7,z=9,star=3,lit=L(7,9),
key=[('十天','H6235','asarat','十'),('叫了來','H7121','vayyiqra','召來'),('從最小的到至大的','H6996','lemiqqaton','從小到大'),('祈求','H8467','tekhinnatkhem','懇求')],
gram=['**{H6235}**（eser，十）：「**過了十天**」。**神的答覆，不是立即來的。****耶利米，等了十天。**','**{H7121}**（qara，叫）：「**都叫了來**」。**這個動詞，是「呼召、召集」。****耶利米把每一個人，從最小的到至大的，都叫了來。**'],
exp=['七節：**過了十天，耶和華的話臨到耶利米。****請你留意這個「十天」。****他們請問神的時候，答案沒有立刻來；耶利米等了十天。****聖經沒有解釋為什麼是十天，我們也不替它加上原因。****我們只看見：神的答覆，有時候不是在我們希望的時間來。**','這十天，也是一個考驗：**一個很急的團體，停在伯利恆旁邊，一天一天，等一個答案。****在這十天裡，他們心裡，已經有了方向：埃及。****等的時候，我們心裡想的，常常就是我們真正想要的答案。**','八、九節，**他就將約哈難和同著他的眾軍長，並眾百姓，從最小的到至大的，都叫了來，對他們說：耶和華以色列的神，就是你們請我在他面前為你們祈求的主，如此說。****請你注意：他把每一個人，都叫了來。****一個重要的信息，不是只傳給少數人，而是傳給所有「請問」的人。**']),
dict(a=10,z=12,star=3,lit=L(10,12),
key=[('住在','H3427','teshevu','居住'),('建立','H1129','uvanitî','建造'),('拆毀','H2040','ehros','拆毀'),('栽植','H5193','venatati','栽種'),('拔出','H5428','etosh','拔出'),('後悔','H5162','nikhamti','後悔、憐憫'),('憐憫','H7356','rakhamim','憐憫')],
gram=['**{H5162}**（nacham，後悔）：「**因我為降與你們的災禍後悔了**」。**這個動詞，是「嘆息、改變心意、憐憫」。****神的「後悔」，不是祂做錯了，而是祂的心，對受苦的人，起了憐憫。**','**{H1129}**（banah，建立）：「**我就建立你們，必不拆毀，栽植你們，並不拔出**」。**這是耶利米一章10節那四個動詞：拔出、拆毀、建立、栽植，現在，倒過來了。****神的應許，是建立與栽植。**'],
exp=['十節，是神的回答的第一部分：**你們若仍住在這地，我就建立你們，必不拆毀，栽植你們，並不拔出，因我為降與你們的災禍後悔了。****請你注意四個動詞：建立、拆毀、栽植、拔出。****耶利米一章10節，神在他一開始的時候說：我今日立你在列國列邦之上，為要拔出、拆毀、毀壞、傾覆，又要建立、栽植。****四十年過去，現在，神把這兩對動詞，在這個團體身上，倒過來說：我要建立，不拆毀；我要栽植，不拔出。**','請你留意：**「仍」這個字：你們若「仍」住在這地。****他們已經離開了米斯巴，停在伯利恆附近；神說，你們若「仍」住在這地，意思是，留下，不要走。****十一節：不要怕你們所怕的巴比倫王。耶和華說：不要怕他！因為我與你們同在，要拯救你們脫離他的手。**','我們要看見這句話的重量：**他們所怕的，是巴比倫王；神說，不要怕他。****四十一章18節，最後一個動詞是懼怕。****四十二章11節，神回答了那個懼怕：不要怕。****而且給了一個理由：因為我與你們同在。****十二節：我也要使他發憐憫，好憐憫你們，叫你們歸回本地。**','這一段，是這一章最美的福音：**神說，我後悔了，我要建立你們，我與你們同在，我要使那個你們所怕的王，向你們發憐憫。****這是一個非常寬廣的應許。****我們不替它加上條件，也不把它變成今日的任何政治應許；我們只讀：神對這一群剩下的人，說了這些話。**']),
dict(a=13,z=17,star=3,lit=L(13,17),
key=[('角聲','H7782','shofar','號角'),('寄居','H1481','lagur','寄居'),('刀劍','H2719','kherev','刀'),('饑荒','H7458','raav','饑荒'),('瘟疫','H1698','dever','瘟疫'),('存留','H8300','sarid','存留的人'),('逃脫','H6412','paleit','逃脫的人')],
gram=['**{H7782}**（shofar，角）：「**聽不見角聲**」。**角聲，是戰爭的警號。****他們想去一個，聽不見警號的地方。**','**{H1698}**（dever，瘟疫）：「**必遭刀劍、饑荒、瘟疫而死**」。**這是耶利米書的三連（十四12；二十一7、9；三十八2）。****這一次，神把這三連，用在埃及，用在他們以為安全的地方。**'],
exp=['十三、十四節，神預先說出了他們的心：**倘若你們說：我們不住在這地，以致不聽從耶和華你們神的話，說：我們不住這地，卻要進入埃及地，在那裡看不見爭戰，聽不見角聲，也不致無食飢餓。我們必住在那裡。****請你注意這三個「看不見」「聽不見」「不致」：看不見爭戰，聽不見角聲，也不致飢餓。****他們想要的，不是壞東西，是和平，是糧食，是安全。**','這是這一章，最令人心痛的地方：**他們想要的，都是好的。****和平、糧食、安全，不是罪。****可是，他們選擇了一個，神說「不要去」的地方，來得到這些。****好的東西，若不是神的方式給的，也可能成為一個網羅。**','十五到十七節，神的回答：**你們若定意要進入埃及，在那裡寄居，你們所懼怕的刀劍，在埃及地必追上你們！你們所懼怕的饑荒，在埃及要緊緊地跟隨你們！你們必死在那裡！****凡定意要進入埃及在那裡寄居的，必遭刀劍、饑荒、瘟疫而死，無一人存留，逃脫我所降與他們的災禍。**','請你想一個很具體的畫面：**他們所怕的刀劍，在埃及追上；他們所怕的饑荒，在埃及跟隨。****他們逃往埃及，是為了逃開懼怕；可是，懼怕本身，跟著他們去了。****我們不能用地理位置，逃開心裡的懼怕。**','我們要小心：**這一段，不是在教我們，今日信徒不可以搬家、不可以去外國、不可以尋求安全。****這是對這一群，在這個具體的時刻，神給的話。****我們讀的是：當神已經說「住在這地，我與你同在」，而人定意去別處，結局是什麼。**']),
dict(a=18,z=19,star=3,lit=L(18,19),
key=[('怒氣','H639','api','怒氣'),('忿怒','H2534','khamati','忿怒'),('辱罵','H423','leala','咒詛、辱罵'),('驚駭','H8047','leshammah','荒涼、驚駭'),('咒詛','H7045','lequlalah','咒詛'),('羞辱','H2781','lekherpah','羞辱'),('警教','H5749','hedoti','警告、作證')],
gram=['**{H5749}**（ud，警教）：「**我今日警教你們了**」。**這個動詞，是「作證、警告」。****它與五節「見證」，是同一個字根：你們請神作見證，現在，神作見證，警告你們。**','**{H2534}**（khemah，忿怒）：「**我也必照樣將我的忿怒傾在你們身上**」。**這是一個很重的句子：神說，我怎樣對待耶路撒冷，我也會怎樣對待你們。****神沒有偏袒。**'],
exp=['十八節，神的話，變得很重：**我怎樣將我的怒氣和忿怒傾在耶路撒冷的居民身上，你們進入埃及的時候，我也必照樣將我的忿怒傾在你們身上，以致你們令人辱罵、驚駭、咒詛、羞辱，你們不得再見這地方。****請你看，這一個「照樣」：神說，我怎樣對耶路撒冷，我也怎樣對你們。****這是一個很誠實的句子：沒有人，因為是「剩下的人」，就可以不聽神的話。**','請你注意：**神對他們說的，是警告，不是咒詛；是預先告訴，不是事後審判。****十九節：所剩下的猶大人哪，耶和華論到你們說：不要進入埃及去。你們要確實地知道，我今日警教你們了。****「警教」這個字，與五節「見證」，是同一個字根。****你們請神作見證，現在，神自己，作了見證。**','這一小段，是這一章的轉折：**前面是應許，後面是警告；前面是「我必建立」，後面是「我必傾倒」。****神不是兩個神，祂是同一個神；祂給了人一個選擇，一邊是生，一邊是死。****我們讀到這裡，不要把神的忿怒，當成報復；經文說，這是一個提前的警告。**']),
dict(a=20,z=22,star=3,lit=L(20,22),
key=[('詭詐自害','H8582','hitittem','使走偏、欺騙'),('禱告','H6419','hitpallel','代禱'),('沒有聽從','H8085','shematem','聽從'),('確實地知道','H3045','yadoa tedeu','知道'),('寄居','H1481','lagur','寄居')],
gram=['**{H8582}**（taah，詭詐自害）：「**你們行詭詐自害**」。**這個動詞，原文是「使走偏、使迷路」。****和合本譯成「行詭詐自害」；意思可以是：你們欺騙了自己的性命。****他們在神面前，說的是一回事，心裡，要的是另一回事。**','**{H8085}**（shama，聽從）：「**你們卻一樣沒有聽從**」。**四十二章，這個動詞，一再出現：四節「我已經聽見」，六節「我們都必聽從」，二十一節「沒有聽從」。****從「聽見」到「聽從」，整個團體，沒有走完。**'],
exp=['二十節，神的僕人，說出了最痛的一句話：**你們行詭詐自害；因為你們請我到耶和華你們的神那裡，說：求你為我們禱告耶和華我們神，照耶和華我們的神一切所說的告訴我們，我們就必遵行。****請你注意：耶利米不是在說，他們一開始就是假的；他說的是，他們「請我」「說我們必遵行」，可是，現在要走的路，與他們起誓的，不一致。**','這個「行詭詐自害」，原文的意思，是「使自己走偏」。**他們起誓說「無論是好是歹，都必聽從」；可是，在聽見答案之前，他們心裡，已經選好了方向。****耶利米說：你們欺騙了自己的性命。****這是一個很誠實的句子：騙的人，是自己；受害的人，也是自己。**','二十一節：**我今日將這話告訴你們，耶和華你們的神，為你們的事差遣我到你們那裡說的，你們卻一樣沒有聽從。****二十二節：現在你們要確實地知道，你們在所要去寄居之地，必遭刀劍、饑荒、瘟疫而死。****這一章，就在這個「確實地知道」上結束。**','請你留意：**這一章，沒有告訴我們，他們有沒有聽從；結局，在下一章。****可是，這句「現在你們要確實地知道」，是神最後一次，把門留下來。****他們聽見了，他們知道了，接下來，是他們的選擇。**','我們可以安靜地，問自己一個問題：**我有沒有，在禱告的時候，說「無論是好是歹，我都聽從」；可是，在答案還沒來之前，心裡，已經選好了方向？****這不是定罪，這是一面鏡子。****耶利米站在那裡，用最清楚的話，說出了這面鏡子。**']),
]
